    sentElsewhere: 'Where else the app connects, and when: a web search of the assistant goes to DuckDuckGo from this computer, or to the cloud provider\'s own search, which then sees the search words. "Sign in" opens the sign-in page your MCP server names, which may be on another site; the app asks first when it is. "Find local servers" and the connection hints check a few known ports on this computer only. "Find on the internet" in a model card asks civitai.com and huggingface.co and loads pictures from their picture servers. Nothing else: no statistics, no update checks, no crash reports.',
